\begin{equation*}
    \mu^\theta_{t-1}(\bm{x}) = \bm{k}^\theta_{t-1}(\bm{x})^T(\mathbf{K}^\theta_{t-1} + \sigma_N^2\mathbf{I})^{-1}\bm{y}_{t-1}
\end{equation*}
