\caption{Length scale Balancing GP-UCB (LB-GP-UCB) }\label{alg:rb_bo}
\begin{algorithmic}[1]
\REQUIRE initial length scale value $\theta_0$; suspected regret bounds $R^\theta(\cdot)$; \\growth function $g(\cdot)$;
confidence parameters $\{\xi_t\}_{t=1}^T$ and
$\{\beta^\theta_t\}_{t=1}^T$ 

\STATE Set $\mathcal{D}_{0} = \emptyset$, $\Theta_1 = \{\theta_0\}$, $S^\theta_0 = \emptyset$ for all $\theta \in \Theta$,  length scale counter $l=1$ \label{alg_line:set_initial_conditions}
\FOR{$t = 1, \dots, T$}
\STATE Select length scale  $\theta_t = \arg\min_{\theta \in \Theta_t} R^\theta(|S_{t-1}^{\theta}| + 1)$ \label{alg_line:select_lengthscale}
\STATE Select point to query $\bm{x}_t =  \underset{\bm{x} \in \mathcal{X}}{\arg\max} \textrm{ UCB}_{t-1}^{\theta_t}(\bm{x})$
\STATE Query the black-box $y_t = f(\bm{x}_t) + \epsilon_t$ 
\STATE Update data buffer $\mathcal{D}_t = \mathcal{D}_{t-1} \cup (x_t, y_t)$
\STATE For each $\theta \in \Theta_{t}$, set $S_t^{\theta} = \{\tau  = 1,\dots, t: \theta_{\tau} = \theta\}$
\STATE Initialise length scales set for new iteration $\Theta_{t+1} := \Theta_{t}$
\IF{ $\forall_{\theta \in \Theta_t} |S_t^\theta| \neq 0$}  \label{alg_line:if_add_new_lengthscale}
\STATE Define $L_t(\theta) = \left( \frac{1}{|S_t^{\theta}|} \sum_{\tau \in S_t^{\theta}}y_{\tau} - \sqrt{\frac{\xi_{t}}{|S_{t}^{\theta}|}} \right)$ \label{alg_line:define_L}
\STATE  \COMMENT{\# \texttt{Eliminate underperforming length scale values}}
\STATE $\Theta_{t+1} = \left\{ \theta \in \Theta_t: L_t(\theta) +  \frac{2}{|S_t^{\theta}|} \sum_{\tau \in S_t^\theta} \beta_\tau^\theta \sigma^\theta_{\tau-1}(\bm{x}_\tau)  \ge  \max_{\theta^\prime \in \Theta_{t}} L_t(\theta^\prime) \right\}$
\label{alg_line:eliminate_lengthscale}
\ENDIF

\IF{$q(l+1) \le \frac{\theta_0}{g(t)}$} \label{alg_line:if_add_legnthscale}
    \STATE $\Theta_{t+1} := \Theta_{t+1} \cup \{q(l+1)\}$ 
    \COMMENT{\# \texttt{Add shorter length scales}} \label{alg_line:add_new_lengthscale}
    \STATE $l := l + 1$ \label{alg_line:update_counter}
\ENDIF
\ENDFOR

\end{algorithmic}

